123	  /// is `AuthExpiredFailure` (i.e. before any `ChatStreamEvent` was ever
124	  /// emitted). Once any event has been emitted, a later `AuthExpiredFailure`
125	  /// is yielded as-is, no retry attempted.
126	  Stream<Either<Failure, ChatStreamEvent>> _streamWithAuthRetry(
127	    Stream<Either<Failure, ChatStreamEvent>> Function() call,
128	  ) async* {
129	    var stream = call();
130	    var canRetry = true;
131	    while (true) {
132	      var sawAnyItem = false;
133	      var restarted = false;
134	      await for (final item in stream) {
135	        if (!sawAnyItem &&
136	            canRetry &&
137	            item.match((f) => f is AuthExpiredFailure, (_) => false)) {
138	          final refreshed = await _sessionRepository.refresh();
139	          if (refreshed.isLeft()) {
140	            yield item;
141	            return;
142	          }
143	          canRetry = false;
144	          stream = call();
145	          restarted = true;
146	          break;
147	        }
148	        sawAnyItem = true;
149	        yield item;
150	      }
151	      if (!restarted) return;
152	    }
153	  }
154	
155	  void _upsertSession(ChatSession session) {
156	    final i = _cachedSessions.indexWhere((s) => s.id == session.id);
157	    if (i >= 0) {
158	      _cachedSessions[i] = session;
159	    } else {
160	      _cachedSessions = [..._cachedSessions, session];
161	    }
162	  }
163	
164	  // Exactly one retry. If it also comes back `AuthExpiredFailure` (a
165	  // pathological double-expiry), that is returned as-is — no second refresh
166	  // attempt, no loop (same shape EntriesRepositoryImpl already uses).
167	  Future<Either<Failure, T>> _retryAfterSilentRefreshIfExpired<T>(
168	    Future<Either<Failure, T>> Function() call,
169	  ) async {
170	    final result = await call();
171	    return result.match(
172	      (f) => f is AuthExpiredFailure
173	          ? _retryAfterSilentRefresh(call)
174	          : Future.value(Left(f)),
175	      (v) => Future.value(Right(v)),
176	    );
177	  }
178	
179	  Future<Either<Failure, T>> _retryAfterSilentRefresh<T>(
180	    Future<Either<Failure, T>> Function() retry,
181	  ) async {
182	    final refreshed = await _sessionRepository.refresh();
183	    return refreshed.match(
184	      (_) => Future.value(
185	        const Left(
186	          AuthExpiredFailure(
187	            message: 'Session could not be renewed',
188	            requestId: '',
189	          ),
190	        ),
191	      ),
192	      (_) => retry(),
193	    );
194	  }
195	}
