196	  ChatMessage _parseMessageFields(Map<String, dynamic> data) => ChatMessage(
197	    id: data['id'] as String,
198	    sessionId: data['sessionId'] as String,
199	    role: ChatRole.values.byName(data['role'] as String),
200	    content: data['content'] as String,
